local locale = GetLocale()
if locale ~= "esES" and locale ~= "esMX" then return end
local _, NS = ...
NS.Tactics = NS.Tactics or {}
local T = NS.Tactics
T[1] = { { "Maldiciones y enfermedades", "Ayuda llevar algo para eliminar una maldición o curar una enfermedad. Por lo demás, un combate fácil: limpia la sala antes de iniciarlo." } }
T[2] = { { "El invocador", "Mata primero al invocador: trae refuerzos. Después, al elemental." }, { "Fuego por todas partes", "Daño de área al grupo, peor cuando el grupo pelea mucho cuerpo a cuerpo." } }
T[3] = { { "Lanzado por la sala", "Lanza por los aires a los jugadores por la sala. Limpia los grupos más cercanos y tanquéalo cerca del túnel, para que nadie caiga en otro grupo." } }
T[4] = { { "Miedo al debilitarse", "Cuando baja su salud, aterroriza a todo el grupo. Prepara algo para romperlo, o limpia la sala antes para que nadie corra hacia otros enemigos." }, { "Las cámaras cerradas", "Tras el combate, abre las cámaras de la sala: unos 24 Dwarven Heirlooms para Important Heirlooms, y la tablilla de The Treaty of Understanding." } }
T[5] = { { "Nova de fuego", "Daño de Fuego a todos los que estén cerca de él, varias veces por combate. Como sanador, mantén con la salud llena al cuerpo a cuerpo." }, { "Gancho", "Un golpe fuerte que empuja al tanque." } }
T[6] = { { "Inmolar", "Quema a un jugador, y luego daño de Fuego cada pocos segundos durante 21 segundos. Interrumpe el hechizo o disipa la quemadura." }, { "Maldición de debilidad", "Reduce el daño físico de un jugador durante 30 segundos. Un mago o un druida puede quitarla." } }
T[7] = { { "Hendedura", "Golpea a su objetivo y al jugador más cercano a este." } }
T[8] = { { "Veneno", "Sus golpes envenenan: daño de Naturaleza con el tiempo. Cura el veneno si puedes." }, { "Ataque insidioso", "Daño adicional al tanque cada 5 a 15 segundos." } }
T[9] = { { "Las arañas del patio", "Nada especial en el jefe en sí. Limpia primero las otras arañas del patio, o se unirán al combate." } }
T[10] = { note = "Limpia el patio, haz clic en la estatua y aguanta durante las oleadas: aparece después.", { "Nova de escarcha", "Daño de escarcha a todo el grupo. Si sanas, guarda maná para todas las oleadas." } }
T[11] = { { "Lanzado por los aires", "Lanza al tanque por los aires y lo aturde 5 segundos. Ojo con la amenaza del daño: el tanque solo lo mantiene aproximadamente la mitad del combate." }, { "Una patrulla", "Limpia su sala antes de iniciar el combate: pasa una patrulla por allí. Su cabeza se recoge para las misiones Abominable Creatures y Unending Torment." } }
T[12] = { { "Choque de llamas", "Su hechizo principal. Se le puede interrumpir y aturdir: organiza las interrupciones y los aturdimientos con el grupo." }, { "Muchos puntos de salud", "El combate más largo de la mazmorra. Sigue interrumpiendo hasta el final." } }
T[13] = { note = "Limpia la casa y la estatua, haz clic en la chimenea y aguanta durante las oleadas. Llega después del último gólem de carne.", { "Veneno", "Envenena a su objetivo. Vigila las barras de salud." }, { "Golpes poderosos", "Pega fuerte: mantén vivo al tanque. Prepara pociones de maná para las oleadas anteriores a él." } }
T[14] = { { "Empujón", "Empuja: limpia primero los grupos que lo rodean, o aterrizarás en uno de ellos." }, { "Escudo antimagia", "Se protege un rato contra los hechizos." }, { "Golpes poderosos", "Pega fuerte: mantén al tanque con la salud llena." } }
T[15] = { { "Descarga de relámpagos", "Mantiene la distancia para lanzarla. Interrúmpelo." }, { "Toque de sanación", "Se cura a sí mismo o a un aliado (lanzamiento de 3 segundos). Interrúmpelo." }, { "Forma de serpiente de Cobrahn", "Al 30% de salud, se transforma en serpiente: golpes más lentos pero más pesados, y empieza a dormir a jugadores." } }
T[16] = { { "Toque de sanación", "Se cura a sí misma o a un aliado. Interrúmpela." }, { "Dormir", "Duerme a un jugador hasta 20 segundos. El daño lo despierta, y disipar magia lo libera." }, { "Aura de espinas", "Daño de Naturaleza a quien la golpee cuerpo a cuerpo." } }
T[17] = { { "Caparazón escudo", "Durante 12 segundos, recibe un 60% menos de daño y ataca más lento pero más fuerte." } }
T[18] = { { "Atronar", "Daño de Naturaleza a todos los que estén cerca de él, y luego ataques y movimiento ralentizados durante 10 segundos." }, { "Toque de sanación", "Se cura a sí mismo o a un aliado. Interrúmpelo." }, { "Dormir", "Duerme a un jugador hasta 20 segundos." } }
T[19] = { { "Relámpagos en cadena", "Un rayo que rebota en un segundo jugador. Interrúmpelo." } }
T[20] = { { "Toque de sanación", "Una curación lenta (3,5 segundos) sobre sí mismo o un aliado. Interrúmpelo." }, { "Dormir", "Duerme a un jugador hasta 20 segundos." }, { "Descarga de relámpagos", "Mantiene la distancia para lanzarla. Interrúmpelo." } }
T[21] = { { "Enredaderas ávidas", "Cuando su objetivo está cerca, derriba e inmoviliza a todos los que estén cerca de él durante 10 segundos. A distancia, mantente lejos." } }
T[22] = { note = "Mata a Dama Anacondra, al Señor Cobrahn, al Señor Pythas y al Señor Serpentis, luego habla con el discípulo de Naralex en la entrada y escóltalo hasta Naralex. Protégelo durante el ritual: Mutanus llega al final.", { "Estruendo de trueno", "Daño de Naturaleza a todos los que estén cerca de él y un aturdimiento de 2,5 segundos." }, { "Pesadilla de Naralex", "Duerme a un jugador hasta 15 segundos." }, { "Aterrorizar", "Hace huir de miedo a un jugador durante 4 segundos." } }
T[23] = { { "Golpe de Rhahk'Zor", "Golpea fuerte al tanque y lo aturde 3 segundos." } }
T[24] = { { "Perforar armadura", "Reduce la armadura del tanque un 75% durante 20 segundos." }, { "Huye a buscar ayuda", "Al 15% de salud, huye a buscar ayuda. Remátalo antes de que se aleje." } }
T[25] = { note = "Pilota la Trituradora de Sneed y sale de ella cuando la destruyen.", { "Desarmar", "Desarma al tanque durante 6 segundos." } }
T[26] = { { "Aterrorizar", "Hace huir de miedo a un jugador durante 4 segundos." }, { "Dolor abrumador", "Reduce la velocidad de lanzamiento de un jugador un 35% durante 15 segundos." } }
T[27] = { { "Metal fundido", "Daño de Fuego cada 3 segundos durante 15 segundos, con ataques y movimiento ralentizados. Interrumpe el lanzamiento de 2 segundos." } }
T[28] = { { "Pisotón violento", "Al 66% y luego al 33% de salud, aturde a todos los que tiene alrededor y va a su cofre a cambiar de armas." }, { "Aporrear", "Con sus dos hachas, desde el 66% de salud: ataques adicionales sobre el tanque." }, { "Poderoso bofetón", "Con su martillo, por debajo del 33% de salud: un golpe fuerte que aturde al tanque 3 segundos." } }
T[29] = { { "Arpón envenenado", "Un lanzamiento de 2 segundos: un golpe y después daño de Naturaleza durante un minuto. Cura el veneno." }, { "Hendedura", "Golpea a su objetivo y al jugador más cercano a este." } }
T[30] = { { "Aporrear", "De vez en cuando, dos ataques adicionales: golpes fuertes sobre el tanque." }, { "Aliados de VanCleef", "A la mitad de su salud, llama a dos pícaros defias." } }
T[31] = { { "Salpicadura de ácido", "Daño de Naturaleza cada 5 segundos durante 30 segundos a todos los que estén cerca de él." }, { "Cocina de Cookie", "Por debajo de la mitad de su salud, se cura (lanzamiento de 2 segundos). Interrúmpelo." }, { "Huye a buscar ayuda", "Al 15% de salud, huye a buscar ayuda. Remátalo antes de que se aleje." } }
T[32] = { { "Drenar alma", "Inmoviliza a un jugador 10 segundos y le drena la salud para curarse. Interrumpe el lanzamiento de 2 segundos o disípalo." } }
T[33] = { { "Golpe retorcido", "El corcel vil aturde a todos los que estén cerca de él durante 3 segundos, y reciben más daño físico. El corcel de sombra no tiene ninguna técnica." } }
T[34] = { { "Drenaje del carnicero", "Drena 350 puntos de maná a su objetivo en cuerpo a cuerpo: un tanque con maná lo nota." } }
T[35] = { { "Velo de sombras", "Maldice a un jugador: las curaciones que recibe son un 75% menores durante 15 segundos. Quítala, sobre todo al tanque." } }
T[36] = { { "Luz sagrada", "Se cura a sí mismo o a un aliado (lanzamiento de 2,5 segundos). Interrúmpelo." }, { "Escudo divino", "Lo vuelve inmune a todo el daño y a todos los hechizos durante 10 segundos." }, { "Martillo de justicia", "Aturde a un jugador durante 4 segundos." } }
T[37] = { { "Pide ayuda", "Al iniciar el combate, llama a las criaturas a menos de 30 metros. Limpia a su alrededor antes." }, { "Rabia aullante", "Al 60%, 40% y 20% de salud, sus golpes se vuelven más fuertes." } }
T[38] = { { "Hendedura", "Golpea a su objetivo y al jugador más cercano a este." }, { "Desjarretar", "Reduce la velocidad de movimiento de su objetivo durante 10 segundos." } }
T[39] = { note = "Llegan de cuatro en cuatro tras la muerte de Fenrus el Devorador: Arugal aparece un instante y los llama.", { "Ofrenda oscura", "Cura a otro abisario. Matadlos de uno en uno." } }
T[40] = { { "Baba tóxica", "Daño de Naturaleza cada 6 segundos y maná drenado, durante 2 minutos. Cura el veneno." } }
T[41] = { { "Huargos de refuerzo", "Cuanto más dura el combate, más huargos tiene con él: un huargo pálido a los 30 a 45 segundos, luego un huargo espumeante y después un horror lupino." } }
T[42] = { { "Descarga del Vacío", "Un virote de Sombras de 3 segundos sobre el tanque, una y otra vez. Interrúmpelo." }, { "Maldición de Arugal", "Convierte a un jugador que no sea el tanque en un Glotón Colmillo Oscuro que lucha por él durante 10 segundos. Quita la maldición." }, { "Puerto de las Sombras", "Se teletransporta entre su saliente, el saliente de arriba y la escalera." }, { "Choque de trueno", "Cuando el tanque llega hasta él: daño de Naturaleza y un aturdimiento de 5 segundos a su alrededor." } }
T[43] = { { "Pisotón", "Golpea a todos los que estén cerca de él." } }
T[44] = { { "Rayo bifurcado", "Daño de Naturaleza en un cono frente a ella (lanzamiento de 2 segundos). Quédate fuera del cono." }, { "Nova de escarcha", "Congela en el sitio a todos los que estén cerca de ella hasta 8 segundos." }, { "Ralentizar", "Reduce la velocidad de movimiento y de ataque de un jugador durante 10 segundos." } }
T[45] = { { "Red", "Inmoviliza a un jugador en el sitio durante 10 segundos." } }
T[46] = { note = "Haz clic en la piedra de la Brasse en el agua: sale de ella.", { "Descarga de escarcha", "Mantiene la distancia para lanzarla: daño de Escarcha y ralentización." }, { "Nova de escarcha", "Inmoviliza a todos los que estén cerca de él hasta 8 segundos." } }
T[47] = { { "Dormir", "Duerme a todos los que estén cerca de él hasta 10 segundos. El daño despierta al que duerme." }, { "Explosión mental", "Daño de Sombras a un jugador (lanzamiento de 1,5 segundos)." } }
T[48] = { note = "Espera en una cueva bajo el agua, debajo del templo del Señor del Crepúsculo Kelris, y muchos grupos se lo pierden. Nada bajo el templo para llegar hasta él." }
T[49] = { note = "Con el Señor del Crepúsculo Kelris muerto, enciende uno tras otro los cuatro fuegos de Aku'mai de su sala. Cada uno trae una oleada de criaturas. Cuando están todas muertas, se abre la puerta de Aku'mai.", { "Nube venenosa", "Daño de Naturaleza cada 5 segundos durante 45 segundos a todos los que estén cerca." }, { "Rabia frenética", "Por debajo del 30% de salud: ráfagas de ataques un 75% más rápidos, una y otra vez." } }
T[50] = { { "Escudo de relámpagos", "El rayo golpea a quien lo toque. Un sacerdote o un chamán puede quitárselo." }, { "Descarga de relámpagos", "Mantiene la distancia para lanzarla. Interrúmpelo." } }
T[51] = { { "Azote con escudo", "Golpea al tanque y lo aturde 2 segundos." }, { "Huye a buscar ayuda", "Al 15% de salud, huye a buscar ayuda. Remátalo antes de que se aleje." } }
T[52] = { { "Huye a buscar ayuda", "Al 15% de salud, huye a buscar ayuda. Remátalo antes de que se aleje." } }
T[53] = { { "Aporrear", "De vez en cuando, dos ataques adicionales: golpes fuertes sobre el tanque." }, { "Enfurecer", "Al 30% de salud, ataca un 30% más rápido hasta el final del combate." } }
T[54] = { { "Cadena de relámpagos", "Un rayo que rebota de jugador en jugador (lanzamiento de 2 segundos). Interrúmpelo." }, { "Sed de sangre", "Acelera sus ataques o los de un aliado un 30% durante 30 segundos. Un sacerdote o un chamán puede quitarla." } }
T[55] = { { "Golpear", "Golpea al objetivo con el daño del arma más 5. Mantén vivo al tanque." } }
T[56] = { { "Bomba de humo", "Aturde a todos los que estén cerca de él durante 4 segundos." }, { "Grito de batalla", "Más poder de ataque para él y sus aliados durante 2 minutos." }, { "Huye a buscar ayuda", "Al 15% de salud, huye a buscar ayuda. Remátalo antes de que se aleje." } }
T[57] = { { "Mucha vida", "No se vio nada especial durante el combate: golpea y tiene mucha vida. Merodea por el pantano del principio entre cocoliscos élite, así que límpialos primero o aléjalo de ellos." } }
T[58] = { note = "Mata a la matriarca raptor en la hierba alta. A su muerte llega una oleada de raptores, y Dienteumbrío acude cuando han muerto.", { "Raptores en la hierba", "Pequeños raptores salen de la hierba cuando la atraviesas y te hacen sangrar." }, { "La oleada previa", "Mata a todos los raptores de la oleada antes de que llegue. Un grupo murió en su primer intento con Dienteumbrío y varios raptores encima a la vez." }, { "Miedo", "El tanque sufre miedo varias veces durante este combate. El Tótem de temblor de un chamán ayuda." } }
T[59] = { { "El campamento Faucedraco", "Está en un campamento Faucedraco. Sus grupos se atraen fácilmente de uno en uno: ocúpate primero de ellos uno por uno. El combate en sí es corto, por ahora no se ha visto nada especial." } }
T[60] = { note = "Permanece inmóvil al final del camino de las arañas. Haz clic en el pequeño cartel junto a él para despertarlo.", { "Reinicio de amenaza", "Reinicia su amenaza y cambia de objetivo durante el combate. Dañadores, reducid el ritmo cuando el tanque lo pierda. Tanque, recupéralo enseguida." } }
T[61] = { note = "Está junto a un círculo ritual en las alcantarillas, rodeado de nigromantes del Kirin Tor.", { "Frenesí profano", "Acelera sus ataques un 75 % durante 20 segundos. Es magia: la Purga de un chamán o el Disipar magia de un sacerdote se lo quita." }, { "Vapulear", "De vez en cuando golpea dos veces más de un solo golpe, y Golpe añade daño a su siguiente ataque: el tanque recibe golpes fuertes." }, { "Levantar a los muertos", "Durante el combate no dejan de levantarse esqueletos alrededor del círculo. Son débiles: mátalos según van llegando." }, { "Desarmar", "Desarma al tanque durante unos 6 segundos." } }
T[62] = { note = "Al principio no está. En las alcantarillas, tras Atrexis, limpia la sala del noreste, la de los puestos de mercado con un pequeño círculo de invocación rosa (no el gran círculo de Atrexis). Un jugador que lleve el Tome of Dalaran hace clic en el círculo y Lyn sale de la gran puerta redonda enrejada. Para conseguir el tomo, recoge el Tomo oscuro de la mesa de la sala del archimago Arugal, en la Ciudadela de Colmillo Oscuro, una vez muerto Arugal, y úsalo en el Leyline Focus, un cristal azul en una trastienda de Molino Ámbar, en el Bosque de Argénteos.", { "Salva de descarga de las Sombras", "Descargas de las Sombras sobre todos a 30 metros de ella." }, { "Maldición de espinas", "1,5 segundos de lanzamiento: una maldición de 3 minutos que daña de vez en cuando al jugador cuando ataca. Quítala." }, { "Esqueletos", "Unos esqueletos se levantan y luchan a su lado. Mátalos." } }
T[63] = { { "Explosión focal", "Tras 3 segundos de lanzamiento, un rayo sale frente a él durante 6 segundos y golpea cuatro veces por segundo. Sal de su trayectoria en cuanto empiece el lanzamiento." }, { "Descarga Arcana", "Su ataque al tanque entre dos rayos, 1,5 segundos de lanzamiento." } }
T[64] = { { "Manamorfo", "Transforma a un jugador en un animal durante 8 segundos. Es magia: disípala." }, { "Silencio", "Silencia durante 10 segundos. Sanadores, mantened la distancia." }, { "Arcane Manalings", "Invoca sin parar pequeños Arcane Manalings. Mátalos con daño de área." } }
T[65] = { { "Avería", "2 segundos de lanzamiento y luego, durante 6 segundos, energía arcana golpea a todos en 25 metros cada 2 segundos, por unos 140 de daño cada vez. A distancia, quedaos a más de 25 metros; cuerpo a cuerpo, salid durante el lanzamiento." }, { "Angry Tomes", "Angry Tomes se lanzan sobre ti por el camino. Mátalos antes de atacar al jefe." } }
T[66] = { { "Debilitar", "2 segundos de lanzamiento: energía arcana drena hasta 200 de maná a todos en 45 metros." }, { "Drenar vitalidad", "Un efecto mágico sobre el tanque: unos 65 de daño Arcano cada 2 segundos durante 10 segundos. Disípalo." }, { "Su sala", "Las criaturas que siguen vivas en su sala se unen al combate cuando lo atacáis. Limpiad la sala primero." } }
T[67] = { note = "Espera tras una barrera mágica en el centro de la ciudad, custodiada por Suffused Treants. Mata a los ents y habla con el magus Fansy Goodbringer, justo al sur de la barrera: la hace caer.", { "Maderas viles", "Unas lianas salen disparadas hacia un jugador y golpean a todos a 5 metros de él, y luego dejan vapores tóxicos en el suelo. Sal de los vapores." }, { "Arrollar", "Pisotea a los jugadores a su lado por unos 100 de daño físico." }, { "Enredar", "Inmoviliza a hasta dos jugadores cerca de él durante unos segundos y les causa daño con el tiempo. Es magia: disípala." } }
T[68] = { note = "La archimaga Modera abre al grupo un portal a la cámara púrpura: lleva hasta él.", { "Maná rebotador", "Un orbe se lanza hacia un jugador al azar y luego vuelve hacia él. Todos los que atraviesa sufren daño Arcano y quedan silenciados 6 segundos: no te pongas entre él y ese jugador." }, { "Polimorfia en masa", "Cuando se queda sin maná, transforma a todo el grupo en animales durante 8 segundos y luego canaliza Evocación durante 6 segundos para rellenarlo." }, { "Ralentizar", "Ralentiza a todos a su alrededor durante 3 segundos: ataques y lanzamientos un 30 % más lentos, movimiento un 70 % más lento." }, { "Quedaos en la sala", "Si alguien sale de la sala durante el combate, vuelve a tener la vida completa." } }
T[69] = { { "Red", "Inmoviliza a todos los que estén cerca de él durante 10 segundos." }, { "Ralentización", "Reduce la velocidad de ataque y de movimiento de un jugador durante 10 segundos, y puede aturdirlo." }, { "Invocar cucaracha mecánica", "Llama a cucarachas mecánicas. Su Actualización las mata y lo cura." } }
T[70] = { note = "Habla con la maestra dinamitera Emi Mechacorta y protégela mientras vuela las dos entradas de la cueva. Llegan troggs en oleadas y después viene Grubbis con Chomper." }
T[71] = { { "Megavoltio", "Daño de Naturaleza en un cono frente a él (lanzamiento de 2 segundos). Solo el tanque se pone delante." }, { "Cadena de relámpagos", "Un rayo que rebota entre los jugadores cercanos (lanzamiento de 2,5 segundos). Interrúmpelo." } }
T[72] = { { "Segar a la multitud", "Golpea a todos los que estén cerca de él e interrumpe sus hechizos. Lanzadores y sanadores, manteneos a distancia." }, { "Golpe en arco", "Golpea a todos en un cono frente a él." }, { "Pisotón", "Golpea a todos los que estén cerca de él." } }
T[73] = { { "Invocar sirviente de fuego", "Llama a dos sirvientes de fuego al empezar el combate." }, { "Bola de fuego", "Mantiene la distancia para lanzarla. Interrúmpelo." }, { "Escudo de fuego II", "Daño de Fuego a todos los que estén cerca de él durante un minuto. Un sacerdote o un chamán puede quitárselo." } }
T[74] = { { "Bombas andantes", "Va encendiendo una a una las cabezas de gnomo alrededor de la sala, y cada una suelta bombas andantes que explotan al llegar a un jugador. El botón junto a una cabeza la apaga. Por debajo de la mitad de su salud, las enciende más rápido." }, { "Empujar", "Empuja al tanque. Por debajo de la mitad de su salud, alcanza a todos los que tiene alrededor." } }
T[75] = { { "Invocar a espíritu de jabalí", "Llama a un Espíritu de jabalí a su lado cada 30 a 45 segundos (1,5 segundos de lanzamiento). Mata a cada uno antes de que llegue el siguiente." }, { "Curación en cadena", "Por debajo del 75 % de vida se cura, y la curación rebota a dos aliados cercanos (2,5 segundos de lanzamiento). Interrúmpelo." } }
T[76] = { { "Dominar mente", "Toma el control de un jugador que no es su objetivo durante 15 segundos (2 segundos de lanzamiento). Interrúmpelo o disipa el efecto del jugador." }, { "Descarga de las Sombras", "Mantiene la distancia para lanzarla. Interrúmpela." } }
T[77] = { { "Pide ayuda", "Cuando lo atacas, llama a las criaturas a menos de 15 metros, incluidos los dos Guardianes de Tuercespina a su lado. Mantén a uno de los dos controlado durante el combate." }, { "Trueno", "Cada 8 a 14 segundos: daño de Naturaleza a todos los cercanos, y sus ataques y movimiento se ralentizan durante 10 segundos." } }
T[78] = { { "Barrera giratoria", "Golpea a todos los que están cerca de él." }, { "Aura de espinas", "Quien lo golpee a él o a un aliado cercano (incluido el Señor Supremo Colmicarnero) sufre daño de Naturaleza." } }
T[79] = { note = "Una protección sella su cueva. Mata a los dos Guardianes Calavera que están delante: cae cuando ambos mueren.", { "Dejado a muerte", "Cada 21 a 35 segundos golpea a un jugador que no es su objetivo, que cae como muerto y ya no puede atacar ni lanzar hechizos. Moverse lo termina." }, { "Arrasada", "Cada 25 a 31 segundos: golpea a todos los cercanos y los aturde 2,5 segundos." }, { "Enfurecer", "Al 60 % de vida y luego al 40 %, ataca un 60 % más rápido y golpea más fuerte durante 2 minutos." } }
T[80] = { note = "Un murciélago raro: no está en todas las partidas. Cuando está, espera en un pequeño hueco de la pared de la cueva de los murciélagos, cerca de Charlga Filonavaja." }
T[81] = { { "Descarga en cadena", "Mantiene la distancia y lo lanza una y otra vez: un rayo que rebota hasta en 3 jugadores (2,5 segundos de lanzamiento). Interrúmpelo." }, { "Pureza", "Cada 9 a 15 segundos es inmune a todos los ataques y hechizos durante 2 segundos." }, { "Renovar", "Cura a un aliado herido, o a ella misma, durante 15 segundos. Un sacerdote o un chamán puede quitarlo." } }
T[82] = { { "Invocar a estruendor de tierra", "Un Estruendor de piedra lo acompaña y lucha a su lado." }, { "Descarga de relámpagos", "Mantiene la distancia para lanzarlo. Interrúmpelo." }, { "Huye en busca de ayuda", "Al 15 % de vida huye en busca de ayuda. Acábalo antes de que se aleje." } }
T[83] = { { "Invocar a estruendor de tierra", "Un Estruendor de piedra lo acompaña y lucha a su lado." }, { "Descarga de relámpagos", "Mantiene la distancia para lanzarlo. Interrúmpelo." } }
T[84] = { { "Palabra de las Sombras: Dolor", "Daño de Sombras a su objetivo cada 3 segundos durante 18 segundos. Un Disipar magia lo quita." } }
T[85] = { note = "Aproximadamente una de cada tres partidas, uno de los tres raros del cementerio está en uno de los seis puntos del mapa: Azshir the Sleepless, Fallen Champion o Ironspine.", { "Llamada de la tumba", "Pasados 60 segundos, daño de Sombras al jugador (2 segundos de lanzamiento). Un mago o un druida puede quitarla antes." }, { "Aterrorizar", "Hace huir de miedo a un jugador durante 4 segundos." }, { "Sifón de alma", "Por debajo de la mitad de su vida, drena a un jugador y al jugador más cercano a este durante 12 segundos, y se cura." } }
T[86] = { note = "Aproximadamente una de cada tres partidas, uno de los tres raros del cementerio está en uno de los seis puntos del mapa: Azshir the Sleepless, Fallen Champion o Ironspine.", { "Mellar", "Golpea a su objetivo y al jugador más cercano a este." }, { "Ejecutar", "Golpea con fuerza a un objetivo con un 20 % de vida o menos. Mantén al tanque por encima." } }
T[87] = { note = "Aproximadamente una de cada tres partidas, uno de los tres raros del cementerio está en uno de los seis puntos del mapa: Azshir the Sleepless, Fallen Champion o Ironspine.", { "Maldición de debilidad", "Reduce el daño físico de todos a menos de 30 metros durante 2 minutos. Un mago o un druida puede quitarla." }, { "Nube de veneno", "Daño de Naturaleza cada 5 segundos durante 45 segundos a todos los cercanos." } }
T[88] = { { "Pica llameante", "Una columna de llamas donde se encuentra un jugador (3 segundos de lanzamiento): daño de Fuego, y luego otra vez cada 3 segundos durante 9 segundos. Sal de ella." }, { "Nova de Fuego", "Daño de Fuego a todos a menos de 10 metros de él." }, { "Choque de llamas", "Daño de Fuego a un jugador, y luego otra vez cada 3 segundos durante 12 segundos. Un Disipar magia lo quita." }, { "Descarga de las Sombras", "Mantiene la distancia para lanzarla. Interrúmpela." } }
T[89] = { { "Perros de caza Escarlata", "Tres perros lo acompañan y atacan con él, y además les da Ansia de sangre. Mátalos primero." }, { "Ansia de sangre", "Acelera sus ataques o los de un aliado un 30 % durante 30 segundos. Un sacerdote o un chamán puede quitarla." }, { "Grito de guerra", "Más poder de ataque para él y sus perros durante 3 minutos." } }
T[90] = { { "Detonación", "A mitad de vida se encierra 8 segundos en una Burbuja Arcana y lanza Detonación (5 segundos de lanzamiento): fuerte daño de Fuego a todos a menos de 30 metros. Sal del alcance antes de la explosión y luego vuelve." }, { "Polimorfia", "Transforma en oveja a un jugador que no es su objetivo hasta 20 segundos (1,5 segundos de lanzamiento). Interrúmpelo o disipa el efecto del jugador." }, { "Silencio", "Silencia a todos a menos de 15 metros durante 10 segundos (1,5 segundos de lanzamiento). Si sanas, quédate más lejos." }, { "Deflagración Arcana", "Cada pocos segundos, daño Arcano a todos a menos de 10 metros. A distancia, mantén la distancia." } }
T[91] = { { "Huracán", "Cada 15 a 25 segundos gira durante 10 segundos y golpea a todos los cercanos. Cuerpo a cuerpo, retrocede hasta que termine." }, { "Mellar", "Golpea a su objetivo y al jugador más cercano a este." }, { "Enfurecer", "Al 30 % de vida ataca un 60 % más rápido y golpea más fuerte durante 2 minutos." }, { "Reclutas Escarlata", "A su muerte, 20 Reclutas Escarlata entran por la puerta de la sala y atacan. Quédate con tu grupo y usa daño de área." } }
T[92] = { { "Maldición de Tuten'kash", "Maldición que reduce un 15 % la velocidad de lanzamiento y ralentiza un 18 % los ataques de los jugadores cercanos durante 15 min. Elimina la maldición." } }
T[93] = { { "Bola de Fuego", "Una bola de fuego a su objetivo, una y otra vez. Interrúmpelo." }, { "Nova de Fuego", "Daño de Fuego a todos los que están cerca de él. Aléjate cuando lo lance." } }
T[94] = { { "Nube enfermiza", "Una nube de enfermedad a su alrededor daña a los cercanos cada 3 segundos. Lucha a distancia o cura la enfermedad." }, { "Enfurecer", "Se enfurece y aumenta su daño y velocidad de ataque durante 2 minutos. Sana más al tanque." } }
T[95] = { { "Dominar mente", "Controla a un jugador durante 10 segundos. Disipa el efecto y evita que haga daño al grupo." }, { "Palabra de las Sombras: Dolor", "Daño de Sombras cada 3 segundos durante 18 segundos. Disípalo." }, { "Curar", "Se cura a sí mismo o a un aliado. Interrumpe el lanzamiento." }, { "Descarga de las Sombras", "Un rayo de daño de Sombra sobre un objetivo, 3 s de lanzamiento. Interrúmpelo." } }
T[96] = { { "Ira de Amnennar", "Empuja a un objetivo hacia atrás. Vuelve a tu posición." }, { "Descarga de Escarcha", "Una descarga de Escarcha que ralentiza a su objetivo, una y otra vez. Interrúmpela." }, { "Nova de Escarcha", "Daño de Escarcha e inmovilización de todos los cercanos. Disipa la inmovilización." } }
T[97] = { { "Toque marchitado", "Enfermedad que causa daño de Sombra y drena maná cada 10 s durante 3 min, y se lo transfiere a él. Cúrala, sobre todo en lanzadores." }, { "Hedor pútrido", "Reduce en 50 la Fuerza y la Agilidad de los jugadores cercanos durante 10 s y les impide lanzar hechizos. Lanzadores, manteneos lejos de él." } }
T[98] = { note = "Yace en el suelo en la pequeña sala junto al altar, como muerto, y se levanta cuando lo atacan.", { "Miedo", "Hace huir aterrorizado a un jugador hasta 8 segundos (1,5 segundos de lanzamiento). Interrúmpelo." }, { "Dormir", "Duerme a todos los cercanos hasta 10 segundos. El daño despierta a un durmiente." }, { "Maldición de sangre", "Un jugador recibe más daño físico durante 10 minutos (2 segundos de lanzamiento). Un mago o un druida puede quitarla." }, { "Curar", "Al 30 % de vida se cura (3 segundos de lanzamiento). Interrúmpelo." } }
T[99] = { { "Pide ayuda", "Cuando lo atacas, llama a todos los defensores Escarlata a menos de 80 metros. Limpia la catedral antes de atacarlo." }, { "Martillo de justicia", "Aturde a un jugador durante 5 segundos." }, { "Escudo divino", "A mitad de vida se vuelve inmune a todo el daño y a todos los hechizos durante 12 segundos." }, { "Aura de castigo", "Daño Sagrado a quien lo golpee cuerpo a cuerpo." } }
T[100] = { note = "Cuando Mograine cae, solo se hace el muerto: ella sale de la sala detrás del altar y ataca.", { "Resurrección Escarlata", "A mitad de vida duerme a toda la sala hasta 10 segundos, corre hacia Mograine y lo resucita. Él le devuelve toda su vida con Imposición de manos, y los dos os combaten juntos." }, { "Acometida Sagrada", "Daño Sagrado a su objetivo (2,5 segundos de lanzamiento). Interrúmpela." }, { "Curar", "Cura al más herido de sus aliados, Mograine incluido (3 segundos de lanzamiento). Interrúmpela." }, { "Palabra de poder: escudo", "La protege del daño hasta 30 segundos. Un sacerdote o un chamán puede quitarlo." } }
T[101] = { { "Embestida exprés", "Aumenta su velocidad de movimiento durante 3 s y añade daño a su primer ataque. Cura a quien reciba el golpe." } }
T[102] = { { "Golpear", "Un golpe cuerpo a cuerpo con daño aumentado a su objetivo. Sana al tanque." } }
T[103] = { { "Embate con escudo", "Golpea a su objetivo y lo aturde durante 2 segundos. Sana durante el aturdimiento." } }
T[104] = { { "Descarga de relámpagos", "Una descarga de Naturaleza a su objetivo. Interrúmpelo." }, { "Cadena de relámpagos", "Relámpago de Naturaleza que salta hasta 3 jugadores. Interrúmpelo y separaos." } }
T[105] = { { "Machaque arqueado", "Un golpe en arco contra todos los que tiene delante. Mantente fuera de su frente." }, { "Mamporro", "Inflige daño adicional a su objetivo y lo empuja hacia atrás. Sana al tanque." }, { "Pisotón de guerra", "Empuja y aturde a todos los cercanos durante 5 segundos. Sana durante el aturdimiento." } }
T[106] = { { "Tormentas de arena", "Invoca una tormenta de arena que lucha por él durante 30 segundos. Mátala o aléjate de ella." }, { "Tormentas de arena", "Invoca una tormenta de arena que lucha por él durante 30 segundos. Mátala o aléjate de ella." } }
T[107] = { { "Látigo de llamas", "Daño de Fuego que reduce la resistencia al Fuego de su objetivo durante 45 segundos. Sana al tanque." }, { "Amplificar llamas", "Aumenta en 100 el daño de Fuego que recibe su objetivo durante 30 segundos. Sana más al tanque." }, { "Nova de Fuego", "Daño de Fuego a todos los cercanos a él. Aléjate cuando lo lance." } }
T[108] = { { "Ansia de sangre", "Aumenta un 30% la velocidad de ataque de un aliado durante 30 segundos. Espera golpes más rápidos al tanque." }, { "Descarga en cadena", "Un relámpago que salta hasta 3 jugadores. Interrúmpelo y separaos." }, { "Descarga de relámpagos", "Un rayo de Naturaleza a su objetivo. Interrúmpelo." }, { "Encoger", "Reduce en 1 la Fuerza y el Aguante de los jugadores cercanos durante 2 minutos. El efecto es menor." } }
T[109] = { { "Tremor terrenal", "Aturde a todos los cercanos a él. Sana durante el aturdimiento." }, { "Enfurecer", "Aumenta su velocidad de ataque un 60% y su daño físico en 50 durante 2 minutos. Sana más al tanque." }, { "Guardianes terráneos despiertos", "Despierta guardianes de tierra que atacan al grupo. Mátalos o aléjalos del sanador." }, { "Despertar al Guarda de la cámara acorazada", "Despierta guardianes de la cámara que se unen al combate. Ocúpate de los enemigos extra antes de que abrumen al grupo." } }
T[110] = { { "Tótem pillaterra", "Invoca un tótem durante 30 segundos que inmoviliza periódicamente a los jugadores cercanos. Destruye el tótem o mantente fuera de su alcance." }, { "Onda de curación de Antu'sul", "Sana a su objetivo entre 2247 y 2608. Interrúmpelo." }, { "Custodia de curación", "Invoca un guardián durante 30 segundos que cura periódicamente a los aliados a su alrededor. Destrúyelo rápido." } }
T[111] = { { "Peste de fiebre", "Un virote de Naturaleza de 4,5 segundos seguido de daño de Naturaleza durante 3 minutos. Interrúmpelo o cura la enfermedad." } }
T[112] = { { "Golpear", "Un golpe cuerpo a cuerpo con daño aumentado a su objetivo. Sana al tanque." } }
T[113] = { { "Guardia de Zum'rah", "Lanza un tótem durante 20 segundos que invoca periódicamente un esqueleto, cada uno de 20 segundos. Destruye primero el tótem." }, { "Onda de curación", "Sana a un aliado con magia de la Naturaleza. Interrúmpelo." }, { "Descarga de las Sombras", "Un rayo de Sombra a su objetivo. Interrúmpelo." }, { "Lluvia de descarga de las Sombras", "Daño de Sombra a todos los jugadores cercanos. Interrúmpelo." } }
T[114] = { { "Peste de fiebre", "Un virote de Naturaleza de 4,5 segundos seguido de daño de Naturaleza durante 3 minutos. Interrúmpelo o cura la enfermedad." } }
T[115] = { { "Renovar", "Cura a un aliado 5 cada 3 segundos durante 20 segundos. Interrúmpelo." }, { "Curar", "Sana a un aliado con magia Sagrada. Interrúmpelo." }, { "Alarido psíquico", "Aterroriza hasta a 5 jugadores cercanos durante 6 segundos. Usa un resguardo contra el miedo o mantén distancia." }, { "Descarga de las Sombras", "Un rayo de Sombra a su objetivo. Interrúmpelo." } }
