T[117] = { { "Ejecutar", "Remata a un jugador con un 20 % de salud o menos con daño adicional. Mantente por encima del 20 % de salud." }, { "Mellar", "Golpea a un objetivo y a su aliado más cercano con daño de arma. No te pegues al tanque." } }
T[118] = { { "Bloqueo mejorado", "Aumenta un 85 % su probabilidad de bloquear durante 6 segundos. Muchos de tus golpes serán bloqueados un rato." }, { "Azote de escudo", "Interrumpe los hechizos de un jugador. Lanzadores, no empecéis hechizos largos sobre él." }, { "Revancha", "Contraataca al objetivo causando de 16 a 20 de daño tras un bloqueo, esquiva o parada. Cura al tanque." } }
