T[120] = { { "Enfurecer", "Aumenta su velocidad de ataque y daño físico durante 2 minutos. Un Disparo tranquilizador o similar ayuda; si no, defensivos y curas." }, { "Tajo profundo", "Golpea a todos en un cono frente a él. Sal del cono, salvo el tanque." }, { "Mellar", "Golpea a un objetivo y a su aliado más cercano con daño de arma. No te pegues al tanque." } }
T[121] = { { "Red", "Inmoviliza a un jugador a menos de 20 m durante 10 s. Protege y cura al jugador inmovilizado." }, { "Disparo de Escarcha", "Ataque de Escarcha a distancia que ralentiza el movimiento un 60 % durante 10 segundos. Acércate o mátalo rápido." } }
