T[123] = { { "Mellar", "Golpea al objetivo y a sus aliados más cercanos, hasta 3 objetivos. No te pongas junto al tanque." }, { "Pinchar", "Daño físico periódico al tanque, cada 2 segundos durante 10 segundos. Sana al tanque." } }
T[124] = { { "Bomba de humo", "Una nube de humo que aturde a todos los cercanos durante 4 segundos. Sana y mantén vivo al tanque." }, { "Multidisparo", "Alcanza hasta cinco objetivos a la vez. Separaos para que sean menos los afectados." } }
T[125] = { { "Golpear", "Un golpe cuerpo a cuerpo fuerte al tanque. Mantén sanado al tanque." }, { "Pisotón de guerra", "Golpea a todos los cercanos, los derriba y los aturde durante 8 s. Cura durante el aturdimiento." } }
T[126] = { { "Enredaderas", "Inmoviliza a un objetivo hasta 10 s, con daño de Naturaleza cada 3 s. Interrúmpelo o disipa el efecto." }, { "Cólera", "Un rayo de daño de Naturaleza sobre un objetivo, 2 s de lanzamiento. Interrúmpelo." }, { "Fuerzas corruptas de la Naturaleza", "Invoca tres Fuerzas de la naturaleza corruptas que luchan por él durante 1 minuto. Mátalas rápido o aléjalas del grupo." } }
