T[133] = { { "Tótem pillaterra", "Invoca un tótem durante 30 segundos que inmoviliza periódicamente a los jugadores cercanos. Destruye el tótem o mantente fuera de su alcance." }, { "Fogonazo", "Invoca un pilar de fuego sobre una zona que quema a todos los que están dentro y causa daño adicional cada 2 segundos durante 8 segundos. Interrúmpelo o sal del fuego." }, { "Onda de curación", "Sana a un aliado con magia de la Naturaleza. Interrúmpelo." } }
